function readHunterAssessment(assessment) {
  if (
    !assessment ||
    typeof assessment !== "object" ||
    Array.isArray(assessment) ||
    typeof assessment.email !== "string" ||
    assessment.email.length === 0 ||
    !["valid", "invalid", "accept_all", "webmail", "disposable", "unknown"].includes(
      assessment.status,
    )
  )
    throw new Error(
      "Hunter did not return a completed email assessment; verification may still be in progress",
    );
  return assessment;
}
function hunterAssessmentResult({ response }) {
  if (!response || typeof response !== "object" || Array.isArray(response) || response.errors)
    throw new Error(
      "Hunter did not return a completed assessment; verification may be pending or rejected",
    );
  return { assessment: readHunterAssessment(response.data) };
}

